/* @ts-self-types="./eventListenerMap.d.ts" */
import { createEventListener } from "./eventListener.js";
import { isServer } from "@solidjs/web";
import { entries } from "@solid-primitives/utils";
//#region src/eventListenerMap.ts
function createEventListenerMap(targets, handlersMap, options) {
	if (isServer) return;
	for (const [eventName, handler] of entries(handlersMap)) if (handler) createEventListener(targets, eventName, handler, options);
}
//#endregion
export { createEventListenerMap };
